fn longest_increasing_streak(nums: &Vec<i32>) -> usize {
    if nums.len() == 0 {
        return 0;
    }

    let mut max_len = 1;
    let mut current_len = 1;

    for i in 1..nums.len() {
        if nums[i] > nums[i - 1] {
            current_len += 1;
        } else {
            if current_len > max_len {
                max_len = current_len;
            }
            current_len = 1;
        }
    }

    if current_len > max_len {
        max_len = current_len;
    }

    max_len
}